(4945789, 718378, 19982, '<td valign="top">I love yellow on blue.  Nice focus on the flower!</td>', 'I love yellow on blue.  Nice focus on the flower!', '2008-09-10 01:09:31.000000', NULL, 1),
(4945796, 719997, 19982, '<td valign="top">Looks like you nailed the focus on the eyes.  Good work!</td>', 'Looks like you nailed the focus on the eyes.  Good work!', '2008-09-10 01:10:13.000000', NULL, 1),
(4945803, 719146, 50641, '<td valign="top">looks good!  nice title :)</td>', 'looks good!  nice title :)', '2008-09-10 01:10:45.000000', NULL, 1),
(4945804, 718231, 19982, '<td valign="top">Beautiful eyes, excellent focus, nice composition and colors.</td>', 'Beautiful eyes, excellent focus, nice composition and colors.', '2008-09-10 01:10:46.000000', NULL, 1),
(4945808, 718871, 19982, '<td valign="top">Pretty!  Love the patterns both in the web as well as the background.  Lovely colors and sharp focus.  Well done.</td>', 'Pretty!  Love the patterns both in the web as well as the background.  Lovely colors and sharp focus.  Well done.', '2008-09-10 01:11:33.000000', NULL, 1),
(4945824, 719452, 19982, '<td valign="top">For anything that has a head, I always prefer the focus be on the eyes.  The wings, even being out of focus, would have made a lovely pattern.  But with the head out of focus, the moth virtually becomes headless.</td>', 'For anything that has a head, I always prefer the focus be on the eyes.  The wings, even being out of focus, would have made a lovely pattern.  But with the head out of focus, the moth virtually becomes headless.', '2008-09-10 01:13:15.000000', NULL, 1),
(4945829, 720174, 98022, '<td valign="top">The water droplets glistening add a nice effect.</td>', 'The water droplets glistening add a nice effect.', '2008-09-10 01:13:55.000000', NULL, 1),
