(4945872, 717968, 75532, '<td valign="top">awww he/she looks so goofy and happy!!</td>', 'awww he/she looks so goofy and happy!!', '2008-09-10 01:18:59.000000', NULL, 1),
(4945882, 717932, 19982, '<td valign="top">For me, shallow DOF is going to be illustrated by either an out of focus foreground or out of focus background, or better yet, both.  I can''t tell that anything in this image is out of focus except the non-existent background.  Everything that is visible seems sharp, so I can''t really judge this image to be shallow DOF.</td>', 'For me, shallow DOF is going to be illustrated by either an out of focus foreground or out of focus background, or better yet, both.  I can''t tell that anything in this image is out of focus except the non-existent background.  Everything that is visible seems sharp, so I can''t really judge this image to be shallow DOF.', '2008-09-10 01:20:16.000000', NULL, 1),
(4945883, 719509, 15711, '<td valign="top">I love the warm rich colors.  Maybe a tad more neg space on the left. :~)</td>', 'I love the warm rich colors.  Maybe a tad more neg space on the left. :~)', '2008-09-10 01:20:18.000000', NULL, 1),
