(4947807, 719504, 66384, '<td valign="top">Eeek, that''s a bit frightening. Nice colors, DOF and interesting subject.</td>', 'Eeek, that''s a bit frightening. Nice colors, DOF and interesting subject.', '2008-09-10 14:40:41.000000', NULL, 1),
(4947809, 720287, 24454, '<td valign="top">VERY cool!  I love this one!  Love it!</td>', 'VERY cool!  I love this one!  Love it!', '2008-09-10 14:41:19.000000', NULL, 1),
(4947811, 718656, 66384, '<td valign="top">Love the background bokeh, and the way you made it a major feature of your composition. Beautiful image.</td>', 'Love the background bokeh, and the way you made it a major feature of your composition. Beautiful image.', '2008-09-10 14:41:59.000000', NULL, 1),
(4947818, 720250, 66384, '<td valign="top">Sorry, but I don''t see much that is shallow about this DOF. Yes, the drum set is slightly OOF, and I like the way the light glints off it, but doesn''t seem to meet this challenge.</td>', 'Sorry, but I don''t see much that is shallow about this DOF. Yes, the drum set is slightly OOF, and I like the way the light glints off it, but doesn''t seem to meet this challenge.', '2008-09-10 14:44:40.000000', NULL, 1),
(4947825, 719975, 22288, '<td valign="top">DOF is small on these types of shots making it more difficult to get the subject isolated. To me I would prefer to have the the details of the flower in focus with some of the petals maybe leaving focus. Maybe if the focal point was midway up the stamen of the flower and the broken stem to the left was not so well focused. Overall I believe you have the right idea - 6</td>', 'DOF is small on these types of shots making it more difficult to get the subject isolated. To me I would prefer to have the the details of the flower in focus with some of the petals maybe leaving focus. Maybe if the focal point was midway up the stamen of the flower and the broken stem to the left was not so well focused. Overall I believe you have the right idea - 6', '2008-09-10 14:47:56.000000', NULL, 1),
(4947828, 719170, 66384, '<td valign="top">The DOF isn''t shallow enough to make the subject really stand out. I am distracted by the woman and clothing in the background. If they were just a blur of colors, my full attention would be on this lovely lady.</td>', 'The DOF isn''t shallow enough to make the subject really stand out. I am distracted by the woman and clothing in the background. If they were just a blur of colors, my full attention would be on this lovely lady.', '2008-09-10 14:48:58.000000', NULL, 1),
(4947830, 720074, 22288, '<td valign="top">Nice use of DOF, but I find the picture to busy - good as an abstract. 6</td>', 'Nice use of DOF, but I find the picture to busy - good as an abstract. 6', '2008-09-10 14:49:23.000000', NULL, 1),
(4947839, 719068, 66384, '<td valign="top">Oh, I really like this abstract. Lovely light and colors, and I like the line you have highlighted with the DOF.</td>', 'Oh, I really like this abstract. Lovely light and colors, and I like the line you have highlighted with the DOF.', '2008-09-10 14:52:40.000000', NULL, 1),
(4947847, 719395, 66384, '<td valign="top">Well, this makes me smile. What a wonderful, and different, subject for shallow DOF. Congratulations on the birth of your son. BTW, I wish the dark upper left corner weren''t there. Maybe after the challenge you could clone that out.</td>', 'Well, this makes me smile. What a wonderful, and different, subject for shallow DOF. Congratulations on the birth of your son. BTW, I wish the dark upper left corner weren''t there. Maybe after the challenge you could clone that out.', '2008-09-10 14:55:21.000000', NULL, 1),
(4947852, 720124, 66384, '<td valign="top">Raspberry! I like the colors, and focus, and its a fun composition. That raspberry looks really delicious.</td>', 'Raspberry! I like the colors, and focus, and its a fun composition. That raspberry looks really delicious.', '2008-09-10 14:57:45.000000', NULL, 1),
(4947857, 719458, 66384, '<td valign="top">Wow, before I noticed the title, I thought it looked like he was on a diving board. I love the colors, the light, the composition, and DOF. I also think the border enhances it nicely.</td>', 'Wow, before I noticed the title, I thought it looked like he was on a diving board. I love the colors, the light, the composition, and DOF. I also think the border enhances it nicely.', '2008-09-10 14:59:45.000000', NULL, 1),
(4947864, 720264, 41129, '<td valign="top">hmm, doesn''t look to me like anything is in focus.. surely a shallow DOF requires part to be sharp and in focus no ?</td>', 'hmm, doesn''t look to me like anything is in focus.. surely a shallow DOF requires part to be sharp and in focus no ?', '2008-09-10 15:03:18.000000', NULL, 1),
(4947865, 719616, 41129, '<td valign="top">too dark for me</td>', 'too dark for me', '2008-09-10 15:03:34.000000', NULL, 1),
(4947867, 719442, 66384, '<td valign="top">Shallow DOF does not seem to apply to this image. The subject would be isolated much better if the background was blurred to just a bit of smooth color.</td>', 'Shallow DOF does not seem to apply to this image. The subject would be isolated much better if the background was blurred to just a bit of smooth color.', '2008-09-10 15:04:22.000000', NULL, 1),
(4947870, 718184, 66384, '<td valign="top">Nice colors and bokeh.</td>', 'Nice colors and bokeh.', '2008-09-10 15:05:24.000000', NULL, 1),
(4947878, 720073, 66384, '<td valign="top">I like the simplicity, contrast, texture, and curve. Good use of shallow DOF.</td>', 'I like the simplicity, contrast, texture, and curve. Good use of shallow DOF.', '2008-09-10 15:07:15.000000', NULL, 1),
(4947879, 718813, 84328, '<td valign="top">beautiful image</td>', 'beautiful image', '2008-09-10 15:07:43.000000', NULL, 1),
(4947885, 719381, 72153, '<td valign="top">I think the face should have been in focus.</td>', 'I think the face should have been in focus.', '2008-09-10 15:09:50.000000', NULL, 1),
