(4947983, 718565, 22288, '<td valign="top">Nice DOF - Blur in center is a bit distracting. It may be more interesting if the blur was more towards the edges. 6</td>', 'Nice DOF - Blur in center is a bit distracting. It may be more interesting if the blur was more towards the edges. 6', '2008-09-10 15:45:04.000000', NULL, 1),
(4947985, 718137, 66384, '<td valign="top">Nice colors, composition, and DOF.</td>', 'Nice colors, composition, and DOF.', '2008-09-10 15:45:44.000000', NULL, 1),
