(4948038, 720242, 95361, '<td valign="top">I think a little bit tighter crop on the bottom would have been a little nicer.  In any case, I give it an 8...I think this pic did something to my subconscious...you should have put the 10 ball in focus. lol</td>', 'I think a little bit tighter crop on the bottom would have been a little nicer.  In any case, I give it an 8...I think this pic did something to my subconscious...you should have put the 10 ball in focus. lol', '2008-09-10 16:15:46.000000', NULL, 1),
(4948062, 720058, 30861, '<td valign="top">Hrrrmmmph.... It''s not affecting my vote (I like this image a lot, actually), but this is not a screw: it is a BOLT. Jejeje</td>', 'Hrrrmmmph.... It''s not affecting my vote (I like this image a lot, actually), but this is not a screw: it is a BOLT. Jejeje', '2008-09-10 16:30:16.000000', NULL, 1),
(4948074, 720158, 71121, '<td valign="top">Perhaps with a title that refers to the spider and its web? Or did I miss something...</td>', 'Perhaps with a title that refers to the spider and its web? Or did I miss something...', '2008-09-10 16:34:45.000000', NULL, 1),
(4948079, 720149, 71121, '<td valign="top">My eye is drawn to the droplets, but they are not in focus. :|</td>', 'My eye is drawn to the droplets, but they are not in focus. :|', '2008-09-10 16:36:13.000000', NULL, 1),
(4948083, 720126, 71121, '<td valign="top">Would have been a real killer with a stronger contrast in lighting between background and foreground! (darker background, brighter hummingbird)</td>', 'Would have been a real killer with a stronger contrast in lighting between background and foreground! (darker background, brighter hummingbird)', '2008-09-10 16:39:00.000000', NULL, 1),
(4948087, 720075, 71121, '<td valign="top">Drops are soo DPC... but I still do like this shot!</td>', 'Drops are soo DPC... but I still do like this shot!', '2008-09-10 16:41:34.000000', NULL, 1),
(4948089, 718756, 71121, '<td valign="top">Nice, too bad that her left eye is a bit blurred.</td>', 'Nice, too bad that her left eye is a bit blurred.', '2008-09-10 16:42:24.000000', NULL, 1),
(4948100, 718565, 71121, '<td valign="top">I find it distracting that the stem is blurry and the apply is blurry in the center. It''s not easy to get round things all in focus with a shallow DOF...</td>', 'I find it distracting that the stem is blurry and the apply is blurry in the center. It''s not easy to get round things all in focus with a shallow DOF...', '2008-09-10 16:49:04.000000', NULL, 1),
(4948102, 718081, 71121, '<td valign="top">JPEG artifacts?</td>', 'JPEG artifacts?', '2008-09-10 16:50:45.000000', NULL, 1),
(4948109, 719572, 71121, '<td valign="top">DOF is only semi-shallow...</td>', 'DOF is only semi-shallow...', '2008-09-10 16:55:13.000000', NULL, 1),
(4948110, 720025, 96915, '<td valign="top">Focus is not quite right, as it seems that there isn''t a point that is sharp</td>', 'Focus is not quite right, as it seems that there isn''t a point that is sharp', '2008-09-10 16:55:33.000000', NULL, 1),
(4948115, 719381, 71121, '<td valign="top">I would have liked it better with focus on her mouth or on the eyes or on the green thing.</td>', 'I would have liked it better with focus on her mouth or on the eyes or on the green thing.', '2008-09-10 16:56:49.000000', NULL, 1),
(4948116, 720170, 96915, '<td valign="top">Effectively demonstrates DOF, but lacking interest</td>', 'Effectively demonstrates DOF, but lacking interest', '2008-09-10 16:57:19.000000', NULL, 1),
(4948118, 719961, 63499, '<td valign="top">I think this would have more impact if it was either in color or had more contrast. I would also like to see the background a little bit more out of focus.</td>', 'I think this would have more impact if it was either in color or had more contrast. I would also like to see the background a little bit more out of focus.', '2008-09-10 16:57:42.000000', NULL, 1),
(4948119, 720213, 71121, '<td valign="top">Wow, what is that!? Some sort of fungus? Great colours, sharpness and abstract blurryness in the background.</td>', 'Wow, what is that!? Some sort of fungus? Great colours, sharpness and abstract blurryness in the background.', '2008-09-10 16:58:20.000000', NULL, 1),
(4948120, 719485, 96915, '<td valign="top">Adorable expression, but the composition leaves a little to be desired.  I''d like less space behind the dog and avoid cutting off his front legs.</td>', 'Adorable expression, but the composition leaves a little to be desired.  I''d like less space behind the dog and avoid cutting off his front legs.', '2008-09-10 16:58:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4948123, 718991, 63499, '<td valign="top">Too much of this photo appears to be in focus for it to be appropriate for a shallow DOF photo.</td>', 'Too much of this photo appears to be in focus for it to be appropriate for a shallow DOF photo.', '2008-09-10 16:59:42.000000', NULL, 1),
(4948125, 720027, 96915, '<td valign="top">I like the contrast of the colors.  My eye wants to see the shine on the front of the tomato in focus, but I see that you focused on the stem, which also would have bothered me to see out of focus.  Maybe a slightly larger depth of field could have captured both parts, while still allowing the background to be blurred</td>', 'I like the contrast of the colors.  My eye wants to see the shine on the front of the tomato in focus, but I see that you focused on the stem, which also would have bothered me to see out of focus.  Maybe a slightly larger depth of field could have captured both parts, while still allowing the background to be blurred', '2008-09-10 17:00:11.000000', NULL, 1),
(4948127, 719947, 96915, '<td valign="top">Image appears flat, and I''m not seeing the shallow depth of field.</td>', 'Image appears flat, and I''m not seeing the shallow depth of field.', '2008-09-10 17:01:05.000000', NULL, 1),
(4948128, 719884, 96915, '<td valign="top">Perfect focus considering how shallow a DOF you''ve captured.</td>', 'Perfect focus considering how shallow a DOF you''ve captured.', '2008-09-10 17:01:48.000000', NULL, 1),
(4948129, 720264, 71121, '<td valign="top">Hmm, is "shallow DOF" OK without an object in focus? I''ll tinker about it. I do like it, but I don''t know if I agree that it meets the challenge. What the heck, so many other people will DNMC it that I can give a good score without regret :)</td>', 'Hmm, is "shallow DOF" OK without an object in focus? I''ll tinker about it. I do like it, but I don''t know if I agree that it meets the challenge. What the heck, so many other people will DNMC it that I can give a good score without regret :)', '2008-09-10 17:02:03.000000', NULL, 1),
(4948130, 717858, 96915, '<td valign="top">While this is a beautiful sunset, I''m not seeing the shallow DOF</td>', 'While this is a beautiful sunset, I''m not seeing the shallow DOF', '2008-09-10 17:02:51.000000', NULL, 1),
(4948132, 719827, 71121, '<td valign="top">Is that real? Background looks flat like if it was printed... intriguing.</td>', 'Is that real? Background looks flat like if it was printed... intriguing.', '2008-09-10 17:04:46.000000', NULL, 1),
