(4950373, 720000, 66384, '<td valign="top">Oooo. Great abstract. Absolutely love the design. Beautiful.</td>', 'Oooo. Great abstract. Absolutely love the design. Beautiful.', '2008-09-11 14:10:03.000000', NULL, 1),
