(4950690, 718755, 98271, '<td valign="top">i love this pic =]</td>', 'i love this pic =]', '2008-09-11 17:00:11.000000', NULL, 1),
(4950841, 720126, 83080, '<td valign="top">Kudos for the in flight capture.  It looks like the ISO may be quite high causing some strong grain (I suppose to allow you shutter headroom to stop the wings).  I''d like to get a feeder like this for my backyard.</td>', 'Kudos for the in flight capture.  It looks like the ISO may be quite high causing some strong grain (I suppose to allow you shutter headroom to stop the wings).  I''d like to get a feeder like this for my backyard.', '2008-09-11 18:58:40.000000', NULL, 1),
