(4951215, 719789, 83080, '<td valign="top">I love this kind of flower.  Just my opinion, but the border (esp. color) really detracts from this for me.  It''s also a bit grainy for my taste.  Nice isolation of the upper flowers and I like the overall composition very much.</td>', 'I love this kind of flower.  Just my opinion, but the border (esp. color) really detracts from this for me.  It''s also a bit grainy for my taste.  Nice isolation of the upper flowers and I like the overall composition very much.', '2008-09-11 22:30:46.000000', NULL, 1),
(4951224, 719962, 67152, '<td valign="top">the color contrast, the placement of the tamarin - all very good - i just wish he was looking at us rather than above us - 7</td>', 'the color contrast, the placement of the tamarin - all very good - i just wish he was looking at us rather than above us - 7', '2008-09-11 22:36:26.000000', NULL, 1),
(4951227, 718081, 7565, '<td valign="top">Nice image but colours are a little too ''extreme'' for me.</td>', 'Nice image but colours are a little too ''extreme'' for me.', '2008-09-11 22:37:20.000000', NULL, 1),
(4951229, 718656, 67152, '<td valign="top">That''s a pretty colorful carpenter bee - the ones around me are almost all black.  Really lovely bokeh background - the composition seems a bit too open for my taste - but it is exquisitely photographed</td>', 'That''s a pretty colorful carpenter bee - the ones around me are almost all black.  Really lovely bokeh background - the composition seems a bit too open for my taste - but it is exquisitely photographed', '2008-09-11 22:37:36.000000', NULL, 1),
(4951231, 720058, 67152, '<td valign="top">supreme shallow DOF - right on the money for this challenge - i love the rust and rustic feel all rolled together</td>', 'supreme shallow DOF - right on the money for this challenge - i love the rust and rustic feel all rolled together', '2008-09-11 22:38:04.000000', NULL, 1),
(4951233, 718197, 67152, '<td valign="top">it sure is paying attention to you...really well done with this image -the background places it in the wild, and the foreground and deer itself are perfectly in focus</td>', 'it sure is paying attention to you...really well done with this image -the background places it in the wild, and the foreground and deer itself are perfectly in focus', '2008-09-11 22:38:54.000000', NULL, 1),
(4951236, 719364, 67152, '<td valign="top">great job of capturing these guys mid flight - i love how the legs on the one are all asunder</td>', 'great job of capturing these guys mid flight - i love how the legs on the one are all asunder', '2008-09-11 22:39:24.000000', NULL, 1),
