(4952853, 719172, 31776, '<td valign="top">Nice image but would have liked to have seen the foreground flower a little bit sharper</td>', 'Nice image but would have liked to have seen the foreground flower a little bit sharper', '2008-09-12 21:20:40.000000', NULL, 1),
(4952855, 719287, 83313, '<td valign="top">A fairly plain shot, so I suspect this was originally for the product shot challenge and it fit in here nicely.</td>', 'A fairly plain shot, so I suspect this was originally for the product shot challenge and it fit in here nicely.', '2008-09-12 21:22:14.000000', NULL, 1),
(4952858, 719507, 83313, '<td valign="top">What kind of cherries are these? The pic seems to have a bit of a yellow cast to it, and a bit dull in the color department. I think it just needs some adjustments to make it pop a bit.</td>', 'What kind of cherries are these? The pic seems to have a bit of a yellow cast to it, and a bit dull in the color department. I think it just needs some adjustments to make it pop a bit.', '2008-09-12 21:25:08.000000', NULL, 1),
(4952862, 720257, 83313, '<td valign="top">Maybe if I was a football fan, this would have more appeal to me. It comes off to me as one of those shots that is good, but still does not appeal to me much. Wish I could nail that down better for you.</td>', 'Maybe if I was a football fan, this would have more appeal to me. It comes off to me as one of those shots that is good, but still does not appeal to me much. Wish I could nail that down better for you.', '2008-09-12 21:27:08.000000', NULL, 1),
(4952867, 720157, 83313, '<td valign="top">Your left a letter out of the title, but it''s okay, because I used the extra letter in my comment.</td>', 'Your left a letter out of the title, but it''s okay, because I used the extra letter in my comment.', '2008-09-12 21:29:00.000000', NULL, 1),
(4952870, 720130, 83313, '<td valign="top">I like the way the water drops seem to amplify the red. There''s a bit of noise grain in the OOF background. Not sure if there is much you can do for it under basic rules, though.</td>', 'I like the way the water drops seem to amplify the red. There''s a bit of noise grain in the OOF background. Not sure if there is much you can do for it under basic rules, though.', '2008-09-12 21:30:30.000000', NULL, 1),
