INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4953222, 718886, 47791, '<td valign="top">Clever title and clever image. Looks great.</td>', 'Clever title and clever image. Looks great.', '2008-09-13 02:49:43.000000', NULL, 1),
(4953223, 720165, 47791, '<td valign="top">A good moody image. I like the composition but the orange cast doesn''t do the image any favours. Still one of the more unique images in this challenge though. 9/10</td>', 'A good moody image. I like the composition but the orange cast doesn''t do the image any favours. Still one of the more unique images in this challenge though. 9/10', '2008-09-13 02:51:00.000000', NULL, 1),
(4953225, 719548, 47791, '<td valign="top">Now this is good.</td>', 'Now this is good.', '2008-09-13 02:53:36.000000', NULL, 1),
(4953246, 719928, 44503, '<td valign="top">shallow DOF??? looks deep</td>', 'shallow DOF??? looks deep', '2008-09-13 09:52:18.000000', NULL, 1),
(4953254, 718184, 88204, '<td valign="top">I like the colors and textures and the use of shallow DoF. I think I''d like it better if the purple onion was off center. Nice shot.</td>', 'I like the colors and textures and the use of shallow DoF. I think I''d like it better if the purple onion was off center. Nice shot.', '2008-09-13 10:06:21.000000', NULL, 1),
(4953255, 719865, 88204, '<td valign="top">This is a really neat shot, although focus seems a bit soft.</td>', 'This is a really neat shot, although focus seems a bit soft.', '2008-09-13 10:07:19.000000', NULL, 1),
(4953257, 719647, 58272, '<td valign="top">I like the colours here. I like that the starfish is your focus but my eye keeps wandering to the cake wanting that to be in focus, too. I think this might also work well taken from a lower perspective.</td>', 'I like the colours here. I like that the starfish is your focus but my eye keeps wandering to the cake wanting that to be in focus, too. I think this might also work well taken from a lower perspective.', '2008-09-13 10:07:34.000000', NULL, 1),
(4953260, 717984, 67152, '<td valign="top">I like the repeating shapes created by the dried corn.  The hue gives this a nice rich yellowish, gold feel. 7</td>', 'I like the repeating shapes created by the dried corn.  The hue gives this a nice rich yellowish, gold feel. 7', '2008-09-13 10:08:43.000000', NULL, 1),
(4953261, 719962, 58272, '<td valign="top">Nice complementary colours! I like the expression captured on your subject!</td>', 'Nice complementary colours! I like the expression captured on your subject!', '2008-09-13 10:09:28.000000', NULL, 1),
