(4956677, 720117, 9602, '<td valign="top">Great background.</td>', 'Great background.', '2008-09-15 16:32:47.000000', NULL, 1),
(4956695, 718597, 98141, '<td valign="top">I think this is a great subject (snake fan). As a snake fan, seeing more of the body of the snake would be cool, I think they tend to wind in very interesting/visually appealing ways. So much of this photo is the subject out of focus that I think if you had included a little more of him (her?) it would balance out the shallow DOF better. Like the title.</td>', 'I think this is a great subject (snake fan). As a snake fan, seeing more of the body of the snake would be cool, I think they tend to wind in very interesting/visually appealing ways. So much of this photo is the subject out of focus that I think if you had included a little more of him (her?) it would balance out the shallow DOF better. Like the title.', '2008-09-15 16:43:35.000000', NULL, 1),
(4956697, 720088, 98141, '<td valign="top">This reminds me of The Little Mermaid and the French chef who is trying to kill Sebastian. I like the warm tones. Perhaps trying it with the crustacean more to one side rather than in the center?</td>', 'This reminds me of The Little Mermaid and the French chef who is trying to kill Sebastian. I like the warm tones. Perhaps trying it with the crustacean more to one side rather than in the center?', '2008-09-15 16:44:59.000000', NULL, 1),
(4956702, 719949, 98141, '<td valign="top">Lovely colors, I like that one can see the same flower in the background, but for some reason this seems rather plain to me. All the visual interest is in the very center of the shot and the blossoms are pretty, but not extraordinary. Try jazzing it up a bit with a different angle or different framing.</td>', 'Lovely colors, I like that one can see the same flower in the background, but for some reason this seems rather plain to me. All the visual interest is in the very center of the shot and the blossoms are pretty, but not extraordinary. Try jazzing it up a bit with a different angle or different framing.', '2008-09-15 16:46:49.000000', NULL, 1),
(4956705, 719419, 98141, '<td valign="top">Very shiny, is that you we can see in the reflection?</td>', 'Very shiny, is that you we can see in the reflection?', '2008-09-15 16:48:22.000000', NULL, 1),
