(4957470, 719487, 97985, '<td valign="top">i like the color and the composition...the position of the yellow ball makes image more interesting than it would be if centered. caught my attention right away.</td>', 'i like the color and the composition...the position of the yellow ball makes image more interesting than it would be if centered. caught my attention right away.', '2008-09-16 01:08:24.000000', NULL, 1),
(4957473, 718992, 97985, '<td valign="top">lovely colors in the specular highlights in the blurred background.  the  vibrant green leavesin the foreground jump off the screen!</td>', 'lovely colors in the specular highlights in the blurred background.  the  vibrant green leavesin the foreground jump off the screen!', '2008-09-16 01:12:42.000000', NULL, 1),
(4957706, 719950, 58272, '<td valign="top">You''ve isolated the water droplet well. I think being a bit bolder in post processing could''ve given this image more punch, some more contrast perhaps.</td>', 'You''ve isolated the water droplet well. I think being a bit bolder in post processing could''ve given this image more punch, some more contrast perhaps.', '2008-09-16 09:55:58.000000', NULL, 1),
(4957708, 718812, 58272, '<td valign="top">You''ve certainly used shallow DOF well here. Just a nit pick but the stray root on the left side sticks out as being distracting for me.</td>', 'You''ve certainly used shallow DOF well here. Just a nit pick but the stray root on the left side sticks out as being distracting for me.', '2008-09-16 09:57:30.000000', NULL, 1),
(4957711, 720177, 58272, '<td valign="top">Took me a second to work out what this was. It''s not usually one of the angles people look for in a bee :P... great sharpnes, and a fun image.</td>', 'Took me a second to work out what this was. It''s not usually one of the angles people look for in a bee :P... great sharpnes, and a fun image.', '2008-09-16 09:59:49.000000', NULL, 1),
(4957712, 720166, 58272, '<td valign="top">I quite like the haphazardness here.</td>', 'I quite like the haphazardness here.', '2008-09-16 09:59:52.000000', NULL, 1),
(4957714, 718568, 58272, '<td valign="top">Nice isolation. Not ovrerly fond of the beige background though.</td>', 'Nice isolation. Not ovrerly fond of the beige background though.', '2008-09-16 10:00:44.000000', NULL, 1),
(4957717, 719425, 58272, '<td valign="top">The highlight cuts the image and makes the left side redundant for me. Perhaps a square crop of the right side...?</td>', 'The highlight cuts the image and makes the left side redundant for me. Perhaps a square crop of the right side...?', '2008-09-16 10:02:16.000000', NULL, 1),
(4957790, 717854, 97760, '<td valign="top">I do like the vibrant green and the very fine, almost over exposed edge of the leaf.</td>', 'I do like the vibrant green and the very fine, almost over exposed edge of the leaf.', '2008-09-16 10:58:03.000000', NULL, 1),
(4957898, 719616, 98141, '<td valign="top">It''s hard to tell what this subject is, more lighting or more profiling would be good I think.</td>', 'It''s hard to tell what this subject is, more lighting or more profiling would be good I think.', '2008-09-16 12:27:29.000000', NULL, 1),
(4957899, 720245, 98141, '<td valign="top">Is this gum?</td>', 'Is this gum?', '2008-09-16 12:27:34.000000', NULL, 1),
