INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4958014, 720000, 26799, '<td valign="top">Really cool. How did you do this?? I would be interested to know the set up.</td>', 'Really cool. How did you do this?? I would be interested to know the set up.', '2008-09-16 13:11:21.000000', NULL, 1),
(4958016, 719052, 26799, '<td valign="top">Too dark for me.</td>', 'Too dark for me.', '2008-09-16 13:11:53.000000', NULL, 1),
(4958018, 719170, 26799, '<td valign="top">Nice shot. Would be nice to see some light reflected onto the face but I have been there before and it''s not always possible is it?? You might have been able to boost the exposure on the face and reduce else where in lightroom or photoshop?</td>', 'Nice shot. Would be nice to see some light reflected onto the face but I have been there before and it''s not always possible is it?? You might have been able to boost the exposure on the face and reduce else where in lightroom or photoshop?', '2008-09-16 13:13:43.000000', NULL, 1),
(4958026, 719653, 26799, '<td valign="top">I could be wrong here but because it''s a shallow DOF I would guess that only portions of this little critter should be in focus. Even though it''s macro about 40% of this frame is in focus. Just my thoughts. Hope it helps.</td>', 'I could be wrong here but because it''s a shallow DOF I would guess that only portions of this little critter should be in focus. Even though it''s macro about 40% of this frame is in focus. Just my thoughts. Hope it helps.', '2008-09-16 13:16:30.000000', NULL, 1),
(4958028, 718261, 26799, '<td valign="top">I don''t know what''s going on with the lines (areas that are not blurred. Was this done with DOF or with photoshop??</td>', 'I don''t know what''s going on with the lines (areas that are not blurred. Was this done with DOF or with photoshop??', '2008-09-16 13:17:40.000000', NULL, 1),
(4958030, 720020, 26799, '<td valign="top">I like this because unlike some of the other shots you really are using shallow DOF. My thoughts would be you could have eliminated most of the black on the sides and went really tight one the spiders legs. Just a thought.</td>', 'I like this because unlike some of the other shots you really are using shallow DOF. My thoughts would be you could have eliminated most of the black on the sides and went really tight one the spiders legs. Just a thought.', '2008-09-16 13:19:11.000000', NULL, 1),
(4958031, 718631, 26799, '<td valign="top">There is nothing shallow about this DOF?? Am I missing something here?</td>', 'There is nothing shallow about this DOF?? Am I missing something here?', '2008-09-16 13:19:50.000000', NULL, 1),
(4958036, 718602, 26799, '<td valign="top">You had the perfect angle on the camera (or you used photoshop) to get the baby''s eye in focus. Good job. A couple hot spots bot generally good tone accross the image. I would be curious to see what the color photograph looked like.</td>', 'You had the perfect angle on the camera (or you used photoshop) to get the baby''s eye in focus. Good job. A couple hot spots bot generally good tone accross the image. I would be curious to see what the color photograph looked like.', '2008-09-16 13:21:18.000000', NULL, 1),
(4958039, 719153, 26799, '<td valign="top">I am curious on this if your light source was closer it would have broght more definition to your specular highlight on the cue ball and imho would ave givin more attention to the cue ball. Also if the white balance on this was a little better the cue ball could have been whiter. Notice how some of the balls in the back ground have shadows going from left to right?? I think it would be cool if all the shadows from the balls could "point" to the back of the cue ball and/or make some sore of interesting pattern that draws additional attention to the cue ball.</td>', 'I am curious on this if your light source was closer it would have broght more definition to your specular highlight on the cue ball and imho would ave givin more attention to the cue ball. Also if the white balance on this was a little better the cue ball could have been whiter. Notice how some of the balls in the back ground have shadows going from left to right?? I think it would be cool if all the shadows from the balls could "point" to the back of the cue ball and/or make some sore of interesting pattern that draws additional attention to the cue ball.', '2008-09-16 13:25:10.000000', NULL, 1),
(4958043, 718881, 26799, '<td valign="top">You definitly get the point of this challenge. This is the shallowest DOF probably in the challenge. It would be nice if there was something more interesting on the other side of the screen.</td>', 'You definitly get the point of this challenge. This is the shallowest DOF probably in the challenge. It would be nice if there was something more interesting on the other side of the screen.', '2008-09-16 13:28:19.000000', NULL, 1),
(4958044, 719478, 26799, '<td valign="top">Is the lighting a little harsh and the pic slightly over exposed. I know it would have been a tough shot with the shadows inside the guitar so not sure what to recommend except multiple exposures.</td>', 'Is the lighting a little harsh and the pic slightly over exposed. I know it would have been a tough shot with the shadows inside the guitar so not sure what to recommend except multiple exposures.', '2008-09-16 13:29:29.000000', NULL, 1),
(4958052, 720168, 26799, '<td valign="top">This is nice and I like how you got the brand "Fender" all in focus. Maybe putting all of the front portion in focus would work better because for me the tip of the guitar being blurred is distracting.</td>', 'This is nice and I like how you got the brand "Fender" all in focus. Maybe putting all of the front portion in focus would work better because for me the tip of the guitar being blurred is distracting.', '2008-09-16 13:31:15.000000', NULL, 1),
(4958055, 720297, 26799, '<td valign="top">Beautiful use of light and I think perfect control of your DOF. You get a 9 from me.</td>', 'Beautiful use of light and I think perfect control of your DOF. You get a 9 from me.', '2008-09-16 13:32:00.000000', NULL, 1),
(4958057, 718166, 26799, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2008-09-16 13:32:40.000000', NULL, 1),
(4958059, 719505, 26799, '<td valign="top">When you look at the eye you can almost see the pupil dialating. Freeky!!! Nice shot. Would have liked to see some spot heal on some distracting skin blemishes.</td>', 'When you look at the eye you can almost see the pupil dialating. Freeky!!! Nice shot. Would have liked to see some spot heal on some distracting skin blemishes.', '2008-09-16 13:33:44.000000', NULL, 1),
(4958061, 720066, 26799, '<td valign="top">You know with a capture like this you have a nice shot. Nice exposure and control of your DOF.</td>', 'You know with a capture like this you have a nice shot. Nice exposure and control of your DOF.', '2008-09-16 13:34:23.000000', NULL, 1),
(4958065, 720204, 98260, '<td valign="top">the DOF is nice, but overall the image is too dark for my liking.  Perhaps having a touch more light in the background would really make this image "pop" :)</td>', 'the DOF is nice, but overall the image is too dark for my liking.  Perhaps having a touch more light in the background would really make this image "pop" :)', '2008-09-16 13:35:28.000000', NULL, 1),
(4958066, 720147, 26799, '<td valign="top">Sorry this red isn''t doing anything for me. Was there a reason for this?? Was this white balance that gave you this effect?? Was it inside some sort of tank with a red heat lamp??</td>', 'Sorry this red isn''t doing anything for me. Was there a reason for this?? Was this white balance that gave you this effect?? Was it inside some sort of tank with a red heat lamp??', '2008-09-16 13:35:28.000000', NULL, 1),
(4958068, 719651, 26799, '<td valign="top">My initial thought would be it would be cool if you showed the polarizer actually bending the light. Nice shot.</td>', 'My initial thought would be it would be cool if you showed the polarizer actually bending the light. Nice shot.', '2008-09-16 13:36:43.000000', NULL, 1),
(4958070, 719352, 98260, '<td valign="top">Is the subject the photog?  The model?  There''s plenty of detail here for the eye to look at and I find mine wandering all over.  Interesting shot nonetheless, I''m just not sure what you were trying to convey. :)</td>', 'Is the subject the photog?  The model?  There''s plenty of detail here for the eye to look at and I find mine wandering all over.  Interesting shot nonetheless, I''m just not sure what you were trying to convey. :)', '2008-09-16 13:37:07.000000', NULL, 1),
(4958073, 720119, 98260, '<td valign="top">Great detail in the fence post.  The OOF portions of the fence leading the eye out of frame is a nice touch.  Nice work here.</td>', 'Great detail in the fence post.  The OOF portions of the fence leading the eye out of frame is a nice touch.  Nice work here.', '2008-09-16 13:37:57.000000', NULL, 1),
(4958074, 720244, 26799, '<td valign="top">And especially impactful because of the date. I gave you a 7 because of the date. Would have been a 5 if you picked September 10th.</td>', 'And especially impactful because of the date. I gave you a 7 because of the date. Would have been a 5 if you picked September 10th.', '2008-09-16 13:38:00.000000', NULL, 1),
