(4959209, 718187, 97225, '<td valign="top">You deserved a much higher score. You might be right about spider aversion.</td>', 'You deserved a much higher score. You might be right about spider aversion.', '2008-09-17 02:51:33.000000', NULL, 0),
(4959210, 720132, 28742, '<td valign="top">Worth the effort indeed. Excellent shot - congrats on 5th!</td>', 'Worth the effort indeed. Excellent shot - congrats on 5th!', '2008-09-17 02:52:05.000000', NULL, 0),
