(4959232, 720000, 57032, '<td valign="top">Too bad you''re blemished by all those red and yellow ribbons you got in those earlier days, hey?<br/> <br/>Congratulations on yet another blue and yet another impeccable shot.</td>', 'Too bad you''re blemished by all those red and yellow ribbons you got in those earlier days, hey? Congratulations on yet another blue and yet another impeccable shot.', '2008-09-17 03:23:20.000000', NULL, 0),
(4959235, 720000, 18450, '<td valign="top">Congrats Irene!!! You and your wonderful experiments are an inspiration!</td>', 'Congrats Irene!!! You and your wonderful experiments are an inspiration!', '2008-09-17 03:27:59.000000', NULL, 0),
(4959236, 718494, 18450, '<td valign="top">Perfect dof!!! Wonderful shot!!</td>', 'Perfect dof!!! Wonderful shot!!', '2008-09-17 03:29:23.000000', NULL, 0),
(4959237, 719501, 18450, '<td valign="top">Beautiful shot Roz! Wonderful colours and dof!</td>', 'Beautiful shot Roz! Wonderful colours and dof!', '2008-09-17 03:31:33.000000', NULL, 0),
(4959244, 720000, 67258, '<td valign="top">Irene,<br/> <br/>Firstly, thank you so much for sharing your techniques with us; secondly congratulations - again!; thirdly, your enthusiasm and delight on ribboning, as though each new one is your first, is wonderful.  Looking forward to seeing many more of your photos gracing the front page before the year is out!</td>', 'Irene, Firstly, thank you so much for sharing your techniques with us; secondly congratulations - again!; thirdly, your enthusiasm and delight on ribboning, as though each new one is your first, is wonderful.  Looking forward to seeing many more of your photos gracing the front page before the year is out!', '2008-09-17 03:44:49.000000', NULL, 0),
(4959252, 720026, 88247, '<td valign="top">No flies on you then!! Well done on yet another  good result xx;-)</td>', 'No flies on you then!! Well done on yet another  good result xx;-)', '2008-09-17 03:56:40.000000', NULL, 0),
(4959255, 720000, 96534, '<td valign="top">Congratulations Irene, you just keep coming up with amazing shots. Do you EVER get sick of being in the kitchen? ;-)</td>', 'Congratulations Irene, you just keep coming up with amazing shots. Do you EVER get sick of being in the kitchen? ;-)', '2008-09-17 03:59:19.000000', NULL, 0),
(4959259, 719364, 15305, '<td valign="top">Congratulations!!! Magnificent shot!!!</td>', 'Congratulations!!! Magnificent shot!!!', '2008-09-17 04:18:39.000000', NULL, 0),
(4959275, 719364, 68956, '<td valign="top">Excellent shot, and at iso 100 too :):)</td>', 'Excellent shot, and at iso 100 too :):)', '2008-09-17 04:56:27.000000', NULL, 0),
(4959278, 720015, 68956, '<td valign="top">Great shot, lovely composition doing the quirky thing and looking out of the frame. Excellent use of DOF to get us to focus on the little guy''s eyes. :)</td>', 'Great shot, lovely composition doing the quirky thing and looking out of the frame. Excellent use of DOF to get us to focus on the little guy''s eyes. :)', '2008-09-17 04:58:00.000000', NULL, 0),
(4959279, 720132, 68956, '<td valign="top">Excellent use of DOF, it works with the image, rather than just being coincidental :)</td>', 'Excellent use of DOF, it works with the image, rather than just being coincidental :)', '2008-09-17 04:59:30.000000', NULL, 0),
(4959281, 719859, 68956, '<td valign="top">Another good example of actually using the DOF to work with the picture :)</td>', 'Another good example of actually using the DOF to work with the picture :)', '2008-09-17 05:00:22.000000', NULL, 0),
(4959287, 718187, 97341, '<td valign="top">I think I voted lower because I really have a phobia of spiders. A little more DOF/focus on the front legs might have helped my score. Great colour/composition.</td>', 'I think I voted lower because I really have a phobia of spiders. A little more DOF/focus on the front legs might have helped my score. Great colour/composition.', '2008-09-17 05:35:48.000000', NULL, 0),
