(4959418, 720119, 47906, '<td valign="top">Great Shot Charlie, I was pulling for you to beat your dad all week. Well with the full point he spotted you I gues you did!!!! Congrats on your great score and finishing so well in your first challenge.</td>', 'Great Shot Charlie, I was pulling for you to beat your dad all week. Well with the full point he spotted you I gues you did!!!! Congrats on your great score and finishing so well in your first challenge.', '2008-09-17 08:21:24.000000', NULL, 0),
(4959420, 717854, 47906, '<td valign="top">Great Shot Peter, I couldnt wait to see which was yours. Love the shapr details and the nice edging on the leaf. Congrats on the excellent score and finish.</td>', 'Great Shot Peter, I couldnt wait to see which was yours. Love the shapr details and the nice edging on the leaf. Congrats on the excellent score and finish.', '2008-09-17 08:24:05.000000', NULL, 0),
